import{createApp}from"vue";import{createPinia}from"pinia";import AddressHydrator from"./address-hydrator";window.initAddressField=element=>{if(!element){console.warn("[GM] The Address field cannot be found.");return}const dataConfig=element.getAttribute("data-config");const config=JSON.parse(dataConfig);const id=config.namespace.id;const app=createApp(AddressHydrator,{rootEl:element,config:config});app.use(createPinia());const vm=app.mount(element);window.__gmAddressInstances??={};window.__gmAddressInstances[id]={app:app,vm:vm,applySettings(partial){const store=vm?.addressStore;if(!store?.settings){return}const s=partial?.settings??partial??{};const storeSettings=store.settings;if(Array.isArray(s.subfieldConfig)){storeSettings.subfieldConfig=s.subfieldConfig}if(typeof s.showMap!=="undefined"){storeSettings.showMap=!!s.showMap}if(s.visibilityToggle){storeSettings.visibilityToggle=s.visibilityToggle}if(s.coordinatesMode){storeSettings.coordinatesMode=s.coordinatesMode}if(s.mapOnSearch){storeSettings.mapOnSearch=s.mapOnSearch}try{store.disconnectAutocomplete();store.connectAutocomplete(element)}catch(e){console.warn("[GM] Error refreshing autocomplete",e)}}};return vm};function tryMount(el){if(!el||el.__gmMounted){return}if(typeof window.initAddressField!=="function"){return}try{window.initAddressField(el);el.__gmMounted=true}catch(e){console.error("[GM] Unable to mount the Address field DOM element.",e)}}function scanAndMount(){document.querySelectorAll("[data-gm-address-root]").forEach(tryMount)}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",scanAndMount,{once:true})}else{scanAndMount()}const observer=new MutationObserver(mutations=>{for(const mutation of mutations){for(const node of mutation.addedNodes){if(node.nodeType!==1){continue}if(node.matches?.("[data-gm-address-root]")){tryMount(node)}node.querySelectorAll?.("[data-gm-address-root]").forEach(tryMount)}}});observer.observe(document.documentElement,{childList:true,subtree:true});(function(){const boot=()=>{scanAndMount()};if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",boot,{once:true})}else{boot()}})();